def bf(planet1, planet2):
    '''
    There are eight planets in our solar system: the closer to the Sun 
    is Mercury, the next one is Venus, then Earth, Mars, Jupiter, Saturn, 
    Uranus, Neptune.
    Write a function that takes two planet names as strings planet1 and planet2. 
    The function should return a tuple containing all planets whose orbits are 
    located between the orbit of planet1 and the orbit of planet2, sorted by 
    the proximity to the sun. 
    The function should return an empty tuple if planet1 or planet2 are not correct 
    planet names. 
    Examples
    bf("Jupiter", "Neptune") ==> ("Saturn", "Uranus")
    bf("Earth", "Mercury") ==> ("Venus")
    bf("Mercury", "Uranus") ==> ("Venus", "Earth", "Mars", "Jupiter", "Saturn")
    '''
    # Check if planet1 or planet2 are not correct
    if planet1 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn"]:
        return ("", "")

    # Create a list of tuples with the planets' names and their orbits
    planets = [(planet1, planet2)]

    # Iterate over the planets and check their orbits
    for planet in planets:
        for other_planet in planets:
            if planet[0] == other_planet[0]:
                if planet[1] > other_planet[1]:
                    return (planet[0], planet[1])
                else:
                    return (other_planet[0], other_planet[1])

    # If no planets are found, return an empty tuple
    return ("", "")
