def replace_max_specialchar(text, max_count):
    # Split the text into words
    words = text.split()

    # Initialize the maximum count
    max_count = 0

    # Iterate through the words
    for word in words:
        # Check if the word is a space, comma, or dot
        if word.isspace() or word.count('.') > max_count:
            # If the word is a space, increase the count
            if word.isspace():
                max_count += 1
            # If the word is a comma, increase the count
            elif word.count(',') > max_count:
                max_count = 1
            # If the word is a dot, increase the count
            elif word.count('.') > max_count:
                max_count = 1

    # Return the result
    return ' '.join(words[:max_count]) + ':' + ' '.join(words[max_count:])


